import {notes} from './question-notes.js?v=9';
import {account,normalizeNickname} from './account-client.js';
const main=document.querySelector('#account-content'),esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let tab='signin';
function nextUrl(){const next=new URLSearchParams(location.search).get('next');if(!next)return'index.html';try{const u=new URL(next,location.href);for(const p of ['index.html','past.html','admin.html'])if(u.origin===location.origin&&u.pathname===new URL(p,location.href).pathname)return u.href;}catch{}return'index.html';}
function message(text,error=true){const e=document.querySelector('#account-message');if(e){e.textContent=text;e.className='form-message '+(error?'error':'success');}}
function authForm(){main.innerHTML=`<h1>个人账户</h1><p class="account-intro">登录后同步收藏、已做记录与练习卷。</p>${!account.enabled?'<div class="account-notice">管理员尚未连接账户数据库，注册和云端同步暂未启用。题库仍可浏览，现有本机记录会保留。</div>':''}${account.error?'<div class="account-notice">账户服务暂时无法连接，请刷新后重试。</div>':''}<div class="auth-grid"><section class="auth-panel"><div class="auth-tabs"><button class="secondary ${tab==='signin'?'active':''}" data-tab="signin">登录</button><button class="secondary ${tab==='signup'?'active':''}" data-tab="signup">注册</button></div><form class="account-form" id="auth-form"><label>昵称（登录用）<input id="nickname" name="username" autocomplete="username" required minlength="2" maxlength="20" placeholder="2—20个中文、字母、数字或下划线"></label><label>密码<input id="password" name="password" type="password" autocomplete="${tab==='signup'?'new-password':'current-password'}" required ${tab==='signup'?'minlength="12"':''} placeholder="${tab==='signup'?'至少12个字符':'输入你的密码'}"></label>${tab==='signup'?'<label>确认密码<input id="password-again" type="password" autocomplete="new-password" required></label><p class="account-small">昵称不区分英文字母大小写，注册后作为固定登录名。管理员可查看昵称、访问时间与学习记录统计，不能查看密码。</p>':''}<button type="submit" class="primary" ${!account.enabled||account.error?'disabled':''}>${tab==='signup'?'免费创建账户':'登录并继续'}</button><p id="account-message" class="form-message" role="status" aria-live="polite"></p></form><p class="account-small">${tab==='signin'?'忘记密码请联系管理员。':'请妥善保存昵称和密码。当前使用昵称注册，不提供邮件自动找回。'}</p></section></div>`;
 main.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;authForm();});document.querySelector('#auth-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button[type=submit]');b.disabled=true;message('正在处理…',false);try{const n=normalizeNickname(document.querySelector('#nickname').value),password=document.querySelector('#password').value;if(tab==='signup'){if(password!==document.querySelector('#password-again').value)throw Error('两次密码不一致');await account.signup(n,password);}else await account.signin(n,password);e.target.reset();location.replace(nextUrl());}catch(err){message(err.message);b.disabled=false;}};}
async function importLegacy(){const [a,b]=await Promise.all([fetch('data/bank.json').then(r=>r.json()),fetch('data/past-bank.json').then(r=>r.json())]);const sources=[['original','pure-practice-state-v1',new Set(a.questions.map(q=>q.id))],['past','pure-past-records-v1',new Set(b.questions.map(q=>q.id))]];let found=0;const jobs=[];for(const [kind,key,ids]of sources){let old;try{old=JSON.parse(localStorage.getItem(key));}catch{}if(!old||!Array.isArray(old.saved)||!Array.isArray(old.done))continue;const own=account.getState(kind),saved=old.saved.filter(x=>ids.has(x)),done=old.done.filter(x=>ids.has(x));found+=new Set([...saved,...done]).size;jobs.push([kind,{saved:[...new Set([...own.saved,...saved])],done:[...new Set([...own.done,...done])]}]);}if(!found){message('这台设备没有可导入的旧记录。',false);return;}if(!confirm(`将这台设备的 ${found} 道旧题记录合并到“${account.user.nickname}”账户？请确认这些记录属于你。`))return;for(const [kind,next]of jobs)await account.commitState(kind,next);await account.load();profile();message('旧记录已合并到当前账户。',false);}
function profile(){const o=account.getState('original'),p=account.getState('past');main.innerHTML=`<h1>你好，${esc(account.user.nickname)}。</h1><p class="account-intro">登录同一账户，在手机和电脑之间继续练习。当前状态：<b id="cloud-status">云端已同步</b>。</p><section class="account-panel"><h2>我的学习记录</h2><div class="account-metrics"><div><b>${o.done.length}</b><span>原创题已做 / 770</span></div><div><b>${p.done.length}</b><span>真题已做 / 323</span></div><div><b>${o.saved.length+p.saved.length}</b><span>收藏题目</span></div></div><div class="account-buttons"><a class="primary button" href="${esc(nextUrl())}">继续浏览题库</a><button class="secondary" id="refresh-cloud">刷新云端记录</button><button class="secondary" id="import-legacy">导入这台设备的旧记录</button><button class="secondary" id="export-cloud">导出自己的记录</button>${account.user.is_admin?'<a class="secondary button" href="admin.html">管理员后台 ↗</a>':''}</div><p class="account-small">旧记录导入采用合并，不删除已有云端记录。退出后，这台设备不会继续显示账户记录。</p><p id="account-message" class="form-message" role="status"></p></section><section class="account-panel"><h2>修改密码</h2><form id="password-form" class="account-form"><label>当前密码<input id="current-password" type="password" autocomplete="current-password" required></label><label>新密码<input id="new-password" type="password" autocomplete="new-password" minlength="12" required></label><label>再次输入新密码<input id="new-password-again" type="password" autocomplete="new-password" required></label><button class="primary" type="submit">更新密码</button></form></section><button class="secondary" id="signout">退出此设备</button>`;
 document.querySelector('#refresh-cloud').onclick=async()=>{try{await account.reload();profile();message('已读取最新云端记录。',false);}catch(e){message(e.message);}};document.querySelector('#import-legacy').onclick=()=>importLegacy().catch(e=>message(e.message));document.querySelector('#export-cloud').onclick=async()=>{await notes.ready;const value={version:1,nickname:account.user.nickname,original:account.getState('original'),past:account.getState('past'),paper:account.paper.value,notes:notes.export(),exportedAt:new Date().toISOString()},url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='pure-practice-account-records.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};document.querySelector('#signout').onclick=async()=>{try{await account.signout();authForm();}catch(e){authForm();message('本设备已退出。');}};document.querySelector('#password-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const password=document.querySelector('#new-password').value;if(password!==document.querySelector('#new-password-again').value)throw Error('两次新密码不一致');await account.changePassword(document.querySelector('#current-password').value,password);e.target.reset();message('密码已更新。',false);}catch(err){message(err.message);}finally{b.disabled=false;}};}
await account.ready;if(account.user)profile();else authForm();account.addEventListener('status',e=>{const el=document.querySelector('#cloud-status');if(el)el.textContent=({synced:'云端已同步',syncing:'正在同步',error:'同步待确认'})[e.detail.value]||'请重新登录';});account.addEventListener('account-switch',()=>location.reload());account.addEventListener('records',()=>{if(account.user)profile();});
